1	package edgefleet
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strconv"
12		"strings"
13	)
14	
15	// AggregateResult is one closed window output line.
16	type AggregateResult struct {
17		Key   string `json:"key"`
18		Start int64  `json:"start"`
19		End   int64  `json:"end"`
20		Count int64  `json:"count"`
21		Sum   int64  `json:"sum"`
22	}
23	
24	// InputError reports a fatal problem with one physical input line.
25	type InputError struct {
26		Line   int
27		Reason string
28	}
29	
30	func (e *InputError) Error() string {
31		return fmt.Sprintf("line %d: %s", e.Line, e.Reason)
32	}
33	
34	type windowID struct {
35		start int64 // inclusive window start in milliseconds since time zero
36		key   string
37	}
38	
39	type windowState struct {
40		end   int64 // exclusive window end in milliseconds
41		count int64
42		sum   int64
43	}
44	
45	// RunAggregate reads line-delimited JSON records from r and writes closed
46	// window results, one JSON object per line, to out. windowMillis must be a
47	// positive signed 64-bit integer. Windows are fixed-length, start at time
48	// zero and use a left-closed right-open interval. Closure is driven solely by
49	// input watermarks: a window whose end is less than or equal to the current
50	// watermark is emitted once, ordered by end ascending and then by key in
51	// UTF-8 byte order. Late events (event time below the current watermark) are
52	// reported on lateLog with their physical line number and skipped. Fatal
53	// record problems return *InputError; results already written to out stay
54	// written, and open windows are not flushed at end of input.
55	//
56	// This is the legacy single-watermark mode: records carry no partition field
57	// and any extra fields are ignored. Use RunAggregatePartitioned to merge
58	// several independent input sources of the same stream.
59	func RunAggregate(r io.Reader, windowMillis int64, out io.Writer, lateLog io.Writer) error {
60		return RunAggregatePartitioned(r, windowMillis, 0, out, lateLog)
61	}
62	
63	// RunAggregatePartitioned reads line-delimited JSON records from r and writes
64	// closed window results, one JSON object per line, to out. windowMillis must
65	// be a positive signed 64-bit integer. partitions selects the input mode:
66	//
67	//   - partitions == 0: legacy single-watermark mode. Records do not carry a
68	//     partition field; any extra fields are ignored.
69	//
70	//   - partitions > 0: partitioned mode, merging partitions independent input
71	//     sources of the same stream. Every event and watermark record must carry
72	//     an integer "partition" in [0,partitions). Each partition advances its
73	//     own watermark; no effective watermark exists until every partition has
74	//     reported at least once, afterwards the effective watermark is the
75	//     minimum of the per-partition values. Window closure and late-event
76	//     checks use this minimum, so one partition's larger watermark can never
77	//     close a window or drop an event ahead of the others. A partition
78	//     watermark may repeat or jump forward but never move backwards.
79	//
80	//     A partition may be declared idle with
81	//     {"type":"idle","partition":p}. An idle partition stops contributing to
82	//     the effective watermark: non-idle partitions that have not reported a
83	//     watermark yet still keep the effective watermark unknown, while a
84	//     partition that never reported may itself be declared idle. When every
85	//     remaining (non-idle) partition has reported, the effective watermark is
86	//     their minimum and the idle record itself can close windows. If all
87	//     partitions are idle, the last produced effective watermark is retained;
88	//     when none was ever produced it stays unknown. Idleness is declared by
89	//     the input only, never inferred from time; a repeated idle declaration
90	//     is a no-op. The next watermark record for that partition resumes it:
91	//     its time must be at least both the partition's previous watermark and
92	//     the current effective watermark. An event for an idle partition is
93	//     fatal; it never resumes implicitly.
94	//
95	// partitions < 0 is an error. Windows, ordering, late-event reporting,
96	// overflow checks and end-of-input behavior are otherwise identical to
97	// RunAggregate.
98	func RunAggregatePartitioned(r io.Reader, windowMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
99		if windowMillis <= 0 {
100			return fmt.Errorf("window length must be a positive signed 64-bit integer, got %d", windowMillis)
101		}
102		if partitions < 0 {
103			return fmt.Errorf("partition count must be a positive signed 64-bit integer, got %d", partitions)
104		}
105		s := &aggregateState{
106			windowMillis:  windowMillis,
107			windows:       make(map[windowID]*windowState),
108			out:           out,
109			lateLog:       lateLog,
110			partitions:    partitions,
111			partWatermark: make(map[int64]*int64),
112			idle:          make(map[int64]bool),
113		}
114	
115		scanner := bufio.NewScanner(r)
116		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024*1024)
117		lineNo := 0
118		for scanner.Scan() {
119			lineNo++
120			line := strings.TrimSuffix(scanner.Text(), "\r")
121			if strings.TrimSpace(line) == "" {
122				continue
123			}
124			if err := s.processLine(line, lineNo); err != nil {
125				return err
126			}
127		}
128		return scanner.Err()
129	}
130	
131	type aggregateState struct {
132		windowMillis int64
133		windows      map[windowID]*windowState
134		out          io.Writer
135		lateLog      io.Writer
136	
137		partitions    int64 // 0 = legacy single-watermark mode
138		watermark     *int64
139		partWatermark map[int64]*int64 // partition -> last watermark; partitioned mode only
140		idle          map[int64]bool   // partitions declared idle in the input; partitioned mode only
141	}
142	
143	func (s *aggregateState) processLine(line string, lineNo int) error {
144		var obj map[string]json.RawMessage
145		if err := json.Unmarshal([]byte(line), &obj); err != nil {
146			return &InputError{Line: lineNo, Reason: "invalid JSON record: " + err.Error()}
147		}
148	
149		typeRaw, ok := obj["type"]
150		if !ok {
151			return &InputError{Line: lineNo, Reason: `missing required string field "type"`}
152		}
153		recordType, err := decodeString(typeRaw, "type")
154		if err != nil {
155			return &InputError{Line: lineNo, Reason: err.Error()}
156		}
157	
158		switch recordType {
159		case "event":
160			return s.processEvent(obj, lineNo)
161		case "watermark":
162			return s.processWatermark(obj, lineNo)
163		case "idle":
164			// Only partitioned mode knows idle declarations; legacy
165			// single-watermark mode treats it as any unknown record type.
166			if s.partitions == 0 {
167				return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
168			}
169			return s.processIdle(obj, lineNo)
170		default:
171			return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
172		}
173	}
174	
175	func (s *aggregateState) processEvent(obj map[string]json.RawMessage, lineNo int) error {
176		key, err := requiredString(obj, "key", lineNo)
177		if err != nil {
178			return err
179		}
180		if key == "" {
181			return &InputError{Line: lineNo, Reason: `field "key" must be a non-empty string`}
182		}
183		eventTime, err := requiredNonNegInt64(obj, "time", lineNo)
184		if err != nil {
185			return err
186		}
187		value, err := requiredInt64(obj, "value", lineNo)
188		if err != nil {
189			return err
190		}
191		p, err := s.requiredPartition(obj, lineNo)
192		if err != nil {
193			return err
194		}
195		if s.partitions > 0 && s.idle[p] {
196			return &InputError{Line: lineNo, Reason: fmt.Sprintf("event for idle partition %d is not allowed; send a watermark to resume it first", p)}
197		}
198	
199		if s.watermark != nil && eventTime < *s.watermark {
200			fmt.Fprintf(s.lateLog, "line %d: late event time=%d below current watermark %d, skipped\n", lineNo, eventTime, *s.watermark)
201			return nil
202		}
203	
204		start := eventTime - eventTime%s.windowMillis
205		if start > math.MaxInt64-s.windowMillis {
206			return &InputError{Line: lineNo, Reason: fmt.Sprintf("window end overflow for key %q window starting at %d with length %d", key, start, s.windowMillis)}
207		}
208		end := start + s.windowMillis
209	
210		id := windowID{start: start, key: key}
211		st := s.windows[id]
212		if st == nil {
213			st = &windowState{end: end}
214			s.windows[id] = st
215		}
216		if st.count == math.MaxInt64 {
217			return &InputError{Line: lineNo, Reason: fmt.Sprintf("event count overflow for key %q window [%d,%d)", key, start, end)}
218		}
219		if value > 0 && st.sum > math.MaxInt64-value {
220			return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
221		}
222		if value < 0 && st.sum < math.MinInt64-value {
223			return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
224		}
225		st.count++
226		st.sum += value
227		return nil
228	}
229	
230	func (s *aggregateState) processWatermark(obj map[string]json.RawMessage, lineNo int) error {
231		next, err := requiredNonNegInt64(obj, "time", lineNo)
232		if err != nil {
233			return err
234		}
235		p, err := s.requiredPartition(obj, lineNo)
236		if err != nil {
237			return err
238		}
239	
240		if s.partitions == 0 {
241			if s.watermark != nil && next < *s.watermark {
242				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark moved backwards from %d to %d", *s.watermark, next)}
243			}
244			s.watermark = &next
245		} else {
246			resuming := s.idle[p]
247			if resuming {
248				// A resume watermark must be at least the partition's previous
249				// watermark and the effective watermark produced while it was
250				// idle; equality on either boundary resumes.
251				if prev, ok := s.partWatermark[p]; ok && next < *prev {
252					return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below its previous watermark %d", next, p, *prev)}
253				}
254				if s.watermark != nil && next < *s.watermark {
255					return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below the current effective watermark %d", next, p, *s.watermark)}
256				}
257				delete(s.idle, p)
258			} else if prev, ok := s.partWatermark[p]; ok && next < *prev {
259				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark for partition %d moved backwards from %d to %d", p, *prev, next)}
260			}
261			s.partWatermark[p] = &next
262			if effective := s.effectiveWatermark(); effective != nil {
263				s.watermark = effective
264			}
265		}
266	
267		if s.watermark == nil {
268			return nil
269		}
270		return s.closeWindows(*s.watermark)
271	}
272	
273	// processIdle declares a partition idle: it stops contributing to the
274	// effective watermark until its next watermark record. The declaration
275	// itself may advance the effective watermark and close windows.
276	func (s *aggregateState) processIdle(obj map[string]json.RawMessage, lineNo int) error {
277		p, err := s.requiredPartition(obj, lineNo)
278		if err != nil {
279			return err
280		}
281		wasIdle := s.idle[p]
282		s.idle[p] = true
283	
284		// Recompute the effective watermark. With the partition excluded, the
285		// remaining non-idle partitions determine it; if every partition is idle
286		// the last produced effective watermark is retained instead of clearing.
287		// Repeated idle declarations do not change the state of the windows.
288		if !wasIdle {
289			if next := s.effectiveWatermark(); next != nil {
290				s.watermark = next
291			}
292		}
293		if s.watermark == nil {
294			return nil
295		}
296		return s.closeWindows(*s.watermark)
297	}
298	
299	// effectiveWatermark returns the minimum watermark over the non-idle
300	// partitions once each of them has reported at least once, or nil
301	// otherwise. When every partition is idle, nil is returned so the caller
302	// keeps the last produced effective watermark.
303	func (s *aggregateState) effectiveWatermark() *int64 {
304		active := s.partitions - int64(len(s.idle))
305		if active <= 0 {
306			return nil
307		}
308		var min int64
309		first := true
310		for p := int64(0); p < s.partitions; p++ {
311			if s.idle[p] {
312				continue
313			}
314			w, ok := s.partWatermark[p]
315			if !ok {
316				return nil
317			}
318			if first || *w < min {
319				min = *w
320				first = false
321			}
322		}
323		return &min
324	}
325	
326	// requiredPartition returns the record's partition index. In legacy mode it
327	// returns 0 without inspecting the record, so extra fields stay ignored.
328	func (s *aggregateState) requiredPartition(obj map[string]json.RawMessage, lineNo int) (int64, error) {
329		if s.partitions == 0 {
330			return 0, nil
331		}
332		p, err := requiredInt64(obj, "partition", lineNo)
333		if err != nil {
334			return 0, err
335		}
336		if p < 0 || p >= s.partitions {
337			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be an integer in range [0,%d), got %d", "partition", s.partitions, p)}
338		}
339		return p, nil
340	}
341	
342	func (s *aggregateState) closeWindows(watermark int64) error {
343		type pending struct {
344			id windowID
345			st *windowState
346		}
347		var ready []pending
348		for id, st := range s.windows {
349			if st.end <= watermark {
350				ready = append(ready, pending{id: id, st: st})
351			}
352		}
353		sort.Slice(ready, func(i, j int) bool {
354			if ready[i].st.end != ready[j].st.end {
355				return ready[i].st.end < ready[j].st.end
356			}
357			return ready[i].id.key < ready[j].id.key
358		})
359		for _, p := range ready {
360			encoded, err := json.Marshal(AggregateResult{
361				Key:   p.id.key,
362				Start: p.id.start,
363				End:   p.st.end,
364				Count: p.st.count,
365				Sum:   p.st.sum,
366			})
367			if err != nil {
368				return err
369			}
370			if _, err := s.out.Write(append(encoded, '\n')); err != nil {
371				return err
372			}
373			delete(s.windows, p.id)
374		}
375		return nil
376	}
377	
378	func requiredString(obj map[string]json.RawMessage, field string, lineNo int) (string, error) {
379		raw, ok := obj[field]
380		if !ok {
381			return "", &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required string field %q", field)}
382		}
383		value, err := decodeString(raw, field)
384		if err != nil {
385			return "", &InputError{Line: lineNo, Reason: err.Error()}
386		}
387		return value, nil
388	}
389	
390	func requiredInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
391		raw, ok := obj[field]
392		if !ok {
393			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required integer field %q", field)}
394		}
395		value, err := decodeInt64(raw, field)
396		if err != nil {
397			return 0, &InputError{Line: lineNo, Reason: err.Error()}
398		}
399		return value, nil
400	}
401	
402	func requiredNonNegInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
403		value, err := requiredInt64(obj, field, lineNo)
404		if err != nil {
405			return 0, err
406		}
407		if value < 0 {
408			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be a non-negative integer, got %d", field, value)}
409		}
410		return value, nil
411	}
412	
413	func decodeString(raw json.RawMessage, field string) (string, error) {
414		trimmed := bytes.TrimSpace(raw)
415		if len(trimmed) == 0 || trimmed[0] != '"' {
416			return "", fmt.Errorf("field %q must be a JSON string, got %s", field, string(trimmed))
417		}
418		var value string
419		if err := json.Unmarshal(trimmed, &value); err != nil {
420			return "", fmt.Errorf("field %q must be a JSON string: %v", field, err)
421		}
422		return value, nil
423	}
424	
425	func decodeInt64(raw json.RawMessage, field string) (int64, error) {
426		trimmed := bytes.TrimSpace(raw)
427		if len(trimmed) == 0 {
428			return 0, fmt.Errorf("field %q must be a signed 64-bit integer", field)
429		}
430		switch trimmed[0] {
431		case '"', '{', '[', 't', 'f', 'n':
432			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
433		}
434		value, err := strconv.ParseInt(string(trimmed), 10, 64)
435		if err != nil {
436			if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
437				return 0, fmt.Errorf("field %q integer out of signed 64-bit range: %s", field, string(trimmed))
438			}
439			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
440		}
441		return value, nil
442	}
