17	// The worked example from the spec: partition 0's early watermark must not
18	// close the window; partition 1's watermark completes the pair and the min
19	// closes [0,1000) with both events merged; a repeated watermark does not
20	// emit the window again.
21	func TestAggregatePartitionedSpecExample(t *testing.T) {
22		input := strings.Join([]string{
