42	// Before every partition has reported at least once there is no effective
43	// watermark: nothing closes and no event is judged late.
44	func TestAggregatePartitionedNoWatermarkUntilAllReport(t *testing.T) {
45		input := strings.Join([]string{
46			`{"type":"watermark","time":5000,"partition":0}`,
47			`{"type":"event","key":"k","time":100,"value":1,"partition":1}`,
48			`{"type":"event","key":"k","time":999,"value":1,"partition":0}`,
49		}, "\n")
50		stdout, stderr, err := runPartitioned(t, input, 1000, 2)
51		if err != nil {
52			t.Fatalf("unexpected error: %v", err)
53		}
54		if stdout != "" {
55			t.Fatalf("no window may close before all partitions report, got %q", stdout)
56		}
57		if stderr != "" {
58			t.Fatalf("no late judgment before all partitions report, got %q", stderr)
59		}
60	}
61	
62	// A single partition's larger watermark must not close windows or drop
63	// events; only the min does.
64	func TestAggregatePartitionedMinWatermarkClosure(t *testing.T) {
65		input := strings.Join([]string{
66			`{"type":"event","key":"k","time":150,"value":1,"partition":0}`,
