68			`{"type":"watermark","time":5000,"partition":0}`, // p0 reports first: no effective watermark yet
69			`{"type":"watermark","time":100,"partition":1}`,  // min = 100, window [0,1000) stays open
70			`{"type":"watermark","time":5000,"partition":0}`, // p0 repeats, min stays 100, still no close
71			`{"type":"watermark","time":1000,"partition":1}`, // min = 1000, closes [0,1000)
72		}, "\n")
73		stdout, stderr, err := runPartitioned(t, input, 1000, 2)
