89		input := strings.Join([]string{
90			``, // line 1 blank
91			`{"type":"watermark","time":2000,"partition":0}`,
92			``, // line 3 blank
93			`{"type":"watermark","time":1000,"partition":1}`,                 // line 4, min = 1000
94			`{"type":"event","key":"k","time":999,"value":1,"partition":0}`,  // line 5 late
95			`{"type":"event","key":"k","time":1000,"value":5,"partition":1}`, // line 6 boundary
96		}, "\n")
97		stdout, stderr, err := runPartitioned(t, input, 1000, 2)
98		if err != nil {
99			t.Fatalf("unexpected error: %v", err)
100		}
101		if stdout != "" {
102			t.Fatalf("window [1000,2000) must stay open, got %q", stdout)
103		}
104		wantErr := "line 5: late event time=999 below current watermark 1000, skipped\n"
105		if stderr != wantErr {
