109	
110	// Events from different partitions for the same key and window merge into
111	// one count and sum; the partition field never reaches output.
112	func TestAggregatePartitionedMergesAcrossPartitions(t *testing.T) {
113		input := strings.Join([]string{
114			`{"type":"event","key":"a","time":100,"value":2,"partition":0}`,
115			`{"type":"event","key":"a","time":200,"value":3,"partition":1}`,
116			`{"type":"event","key":"a","time":300,"value":-1,"partition":2}`,
117			`{"type":"event","key":"b","time":400,"value":7,"partition":0}`,
118			`{"type":"watermark","time":1000,"partition":0}`,
