150			`{"key":"a","start":0,"end":1000,"count":1,"sum":1}`,
151			`{"key":"a","start":1000,"end":2000,"count":1,"sum":1}`,
152			`{"key":"z","start":1000,"end":2000,"count":1,"sum":1}`,
153			``,
154		}, "\n")
155		if stdout != want {
156			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
157		}
158	}
159	
160	// Per-partition watermarks may repeat or jump forward, but never move
161	// backwards — even when the regression would not change the overall min.
162	func TestAggregatePartitionedWatermarkRegression(t *testing.T) {
163		cases := []struct {
164			name      string
165			input     string
166			wantLine  int
167			wantInMsg string
168		}{
169			{
170				"regression changes min",
171				strings.Join([]string{
172					`{"type":"watermark","time":100,"partition":0}`,
173					`{"type":"watermark","time":100,"partition":1}`,
174					`{"type":"watermark","time":50,"partition":0}`,
175				}, "\n"),
176				3, "partition 0",
177			},
178			{
179				"regression hidden behind min",
180				strings.Join([]string{
181					`{"type":"watermark","time":100,"partition":0}`,
182					`{"type":"watermark","time":100,"partition":1}`,
183					`{"type":"watermark","time":200,"partition":1}`, // p1 jumps, min stays 100
184					`{"type":"watermark","time":150,"partition":1}`, // p1 regresses 200 -> 150
185				}, "\n"),
186				4, "partition 1",
187			},
188			{
189				"regression before all report",
190				strings.Join([]string{
191					`{"type":"watermark","time":100,"partition":0}`,
192					`{"type":"watermark","time":90,"partition":0}`,
193				}, "\n"),
194				2, "partition 0",
195			},
196		}
197		for _, tc := range cases {
198			t.Run(tc.name, func(t *testing.T) {
199				_, _, err := runPartitioned(t, tc.input, 1000, 2)
200				if err == nil {
201					t.Fatal("expected error, got nil")
202				}
203				inputErr, ok := err.(*InputError)
204				if !ok {
205					t.Fatalf("expected *InputError, got %T: %v", err, err)
206				}
207				if inputErr.Line != tc.wantLine {
208					t.Errorf("line = %d, want %d", inputErr.Line, tc.wantLine)
209				}
210				if !strings.Contains(inputErr.Reason, tc.wantInMsg) {
211					t.Errorf("reason = %q, want substring %q", inputErr.Reason, tc.wantInMsg)
212				}
213			})
214		}
215	}
216	
217	// Missing, mistyped and out-of-range partition fields are fatal with the
218	// physical line number.
219	func TestAggregatePartitionedPartitionFieldErrors(t *testing.T) {
220		cases := []struct {
221			name      string
222			input     string
223			wantLine  int
224			wantInMsg string
225		}{
226			{"event missing partition", `{"type":"event","key":"k","time":1,"value":1}` + "\n", 1, `"partition"`},
227			{"watermark missing partition", `{"type":"watermark","time":100}` + "\n", 1, `"partition"`},
